@import "@fontsource-variable/manrope";

/* Light (faithful): warm cream paper (#f5f1ee), white cards (#fff), pure black ink and
   rules, one hot orange (#ff5e2b) with black text on it, and a yellow → red pair
   (#ffa41c → #ff362a) for the gradient headline. Soft lines are black at 30%. */
:root {
  --background: oklch(0.96 0.006 59.7);
  --foreground: oklch(0 0 0);
  --card: oklch(1 0 0);
  --card-foreground: oklch(0 0 0);
  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0 0 0);
  --primary: oklch(0.688 0.206 37);
  --primary-foreground: oklch(0 0 0);
  --secondary: oklch(0.921 0.006 59.6);
  --secondary-foreground: oklch(0 0 0);
  --muted: oklch(0.921 0.006 59.6);
  --muted-foreground: oklch(0.504 0.012 39.4);
  --accent: oklch(0.921 0.006 59.6);
  --accent-foreground: oklch(0 0 0);
  --destructive: oklch(0.571 0.218 27.7);
  --destructive-foreground: oklch(1 0 0);
  --border: oklch(0 0 0 / 30%);
  --input: oklch(0 0 0 / 30%);
  --ring: oklch(0.688 0.206 37);
  --highlight: oklch(0.792 0.167 68.9);
  --highlight-foreground: oklch(0 0 0);
  --glow: oklch(0.65 0.236 29);
  --chart-1: oklch(0.688 0.206 37);
  --chart-2: oklch(0.792 0.167 68.9);
  --chart-3: oklch(0.65 0.236 29);
  --chart-4: oklch(0.532 0.26 267.1);
  --chart-5: oklch(0.645 0.014 35.7);
  --sidebar: oklch(0.96 0.006 59.7);
  --sidebar-foreground: oklch(0 0 0);
  --sidebar-primary: oklch(0.688 0.206 37);
  --sidebar-primary-foreground: oklch(0 0 0);
  --sidebar-accent: oklch(0.921 0.006 59.6);
  --sidebar-accent-foreground: oklch(0 0 0);
  --sidebar-border: oklch(0 0 0 / 30%);
  --sidebar-ring: oklch(0.688 0.206 37);

  --typeface-body: "Manrope Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-display: "Manrope Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-mono: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  --radius: 0.5rem;
  --page-width: 90rem;
  /* 21px on phones, 40px at 1440 */
  --page-gutter: clamp(1.3125rem, 2.78vw, 2.5rem);
  /* ~70px on phones, ~128px at 1440 */
  --section-y: clamp(4.375rem, 8.9vw, 8rem);
}

/* Dark: the stage colours. The original's black panels (hero, about band, footer) use this
   palette locally through the `dark` class: pure black cards, white text. As a whole-page
   mode, the cream paper becomes a warm near-black (#141111) so black panels still read as
   frames; quiet fills are the original's dark greys (#241f1f, #413a3a). */
.dark {
  --background: oklch(0.181 0.005 17.6);
  --foreground: oklch(1 0 0);
  --card: oklch(0 0 0);
  --card-foreground: oklch(1 0 0);
  --popover: oklch(0.214 0.006 17.7);
  --popover-foreground: oklch(1 0 0);
  --primary: oklch(0.688 0.206 37);
  --primary-foreground: oklch(0 0 0);
  --secondary: oklch(0.245 0.008 17.7);
  --secondary-foreground: oklch(1 0 0);
  --muted: oklch(0.245 0.008 17.7);
  --muted-foreground: oklch(0.76 0.01 40);
  --accent: oklch(0.356 0.01 17.6);
  --accent-foreground: oklch(1 0 0);
  --destructive: oklch(0.661 0.218 25.5);
  --destructive-foreground: oklch(1 0 0);
  --border: oklch(1 0 0 / 30%);
  --input: oklch(1 0 0 / 30%);
  --ring: oklch(0.688 0.206 37);
  --highlight: oklch(0.792 0.167 68.9);
  --highlight-foreground: oklch(0 0 0);
  --glow: oklch(0.65 0.236 29);
  --chart-1: oklch(0.688 0.206 37);
  --chart-2: oklch(0.792 0.167 68.9);
  --chart-3: oklch(0.65 0.236 29);
  --chart-4: oklch(0.6 0.22 267);
  --chart-5: oklch(0.645 0.014 35.7);
  --sidebar: oklch(0.145 0 0);
  --sidebar-foreground: oklch(1 0 0);
  --sidebar-primary: oklch(0.688 0.206 37);
  --sidebar-primary-foreground: oklch(0 0 0);
  --sidebar-accent: oklch(0.245 0.008 17.7);
  --sidebar-accent-foreground: oklch(1 0 0);
  --sidebar-border: oklch(1 0 0 / 20%);
  --sidebar-ring: oklch(0.688 0.206 37);
}
